#include <iostream>
#include <string>
#include <vector>
#include <cstddef>

enum class Estado {
    preparado, enviado, cancelado
};

struct PedidoInvalido {};

class Pedido {
public:
    Pedido(std::string codigo, int unidades) : codigo_{codigo}, unidades_{unidades} {
        if (codigo_.empty() || unidades_ < 1 || unidades_ > 20) {
            throw PedidoInvalido{};
        }
    }
    std::string codigo() const { return codigo_; }
    int unidades() const { return unidades_; }
    Estado estado() const { return estado_; }
    bool cambiar_unidades(int nuevas) {
        if (estado_ != Estado::preparado || nuevas < 1 || nuevas > 20) { return false; }
        unidades_ = nuevas;
        return true;
    }
    bool enviar() {
        if (estado_ != Estado::preparado) { return false; }
        estado_ = Estado::enviado;
        return true;
    }
    bool cancelar() {
        if (estado_ != Estado::preparado) { return false; }
        estado_ = Estado::cancelado;
        return true;
    }
private:
    std::string codigo_;
    int unidades_;
    Estado estado_ = Estado::preparado;
};

struct Solicitud { std::string codigo; int unidades; };

int main() {
    std::vector<Pedido> pedidos{{"A", 2}, {"B", 5}, {"C", 1}};
    pedidos.at(1).enviar();
    std::vector<Solicitud> solicitudes{{"A", 6}, {"B", 3}, {"X", 4}, {"A", 21}, {"C", 20}};
    for (const auto& solicitud : solicitudes) {
        std::size_t posicion = pedidos.size();
        for (std::size_t i = 0; i < pedidos.size(); ++i) {
            if (pedidos[i].codigo() == solicitud.codigo) { posicion = i; break; }
        }
        std::cout << solicitud.codigo << ":";
        if (posicion == pedidos.size()) {
            std::cout << "Absente\n";
        } else if (pedidos[posicion].cambiar_unidades(solicitud.unidades)) {
            std::cout << "Appliquée\n";
        } else {
            std::cout << "Refusée\n";
        }
    }
    int total = 0;
    for (const auto& pedido : pedidos) {
        std::cout << pedido.codigo() << ":" << pedido.unidades() << ";";
        total += pedido.unidades();
    }
    std::cout << " Total:" << total;
    return 0;
}

